34	import org.apache.ratis.grpc.util.ZeroCopyMessageMarshaller;
35	import org.apache.ratis.thirdparty.com.google.protobuf.MessageLite;
36	import org.apache.ratis.thirdparty.io.grpc.MethodDescriptor;
37	import org.apache.ratis.thirdparty.io.grpc.ServerCallHandler;
38	import org.apache.ratis.thirdparty.io.grpc.ServerServiceDefinition;
39	import org.apache.ratis.thirdparty.io.grpc.stub.CallStreamObserver;
40	import org.apache.ratis.thirdparty.io.grpc.stub.StreamObserver;
41	import org.slf4j.Logger;
42	import org.slf4j.LoggerFactory;
43	
44	import static org.apache.hadoop.hdds.protocol.datanode.proto.IntraDatanodeProtocolServiceGrpc.getDownloadMethod;
45	import static org.apache.hadoop.hdds.protocol.datanode.proto.IntraDatanodeProtocolServiceGrpc.getUploadMethod;
46	import static org.apache.hadoop.ozone.container.replication.CopyContainerCompression.fromProto;
47	
48	/**
49	 * Service to make containers available for replication.
50	 */
51	public class GrpcReplicationService extends
52	    IntraDatanodeProtocolServiceGrpc.IntraDatanodeProtocolServiceImplBase {
53	
54	  private static final Logger LOG =
55	      LoggerFactory.getLogger(GrpcReplicationService.class);
56	
57	  static final int BUFFER_SIZE = 1024 * 1024;
58	
59	  private final ContainerReplicationSource source;
60	  private final ContainerImporter importer;
61	
62	  private final boolean zeroCopyEnabled;
63	
64	  private final ZeroCopyMessageMarshaller<SendContainerRequest>
65	      sendContainerZeroCopyMessageMarshaller;
66	
67	  private final ZeroCopyMessageMarshaller<CopyContainerRequestProto>
68	      copyContainerZeroCopyMessageMarshaller;
69	
70	  public GrpcReplicationService(ContainerReplicationSource source,
71	      ContainerImporter importer, boolean zeroCopyEnabled) {
72	    this.source = source;
73	    this.importer = importer;
74	    this.zeroCopyEnabled = zeroCopyEnabled;
75	
76	    if (zeroCopyEnabled) {
77	      sendContainerZeroCopyMessageMarshaller = new ZeroCopyMessageMarshaller<>(
78	          SendContainerRequest.getDefaultInstance());
79	      copyContainerZeroCopyMessageMarshaller = new ZeroCopyMessageMarshaller<>(
80	          CopyContainerRequestProto.getDefaultInstance());
81	    } else {
82	      sendContainerZeroCopyMessageMarshaller = null;
83	      copyContainerZeroCopyMessageMarshaller = null;
84	    }
85	  }
86	
87	  public ServerServiceDefinition bindServiceWithZeroCopy() {
88	    ServerServiceDefinition orig = super.bindService();
89	    if (!zeroCopyEnabled) {
90	      LOG.info("Zerocopy is not enabled.");
91	      return orig;
92	    }
93	
94	    Set<String> methodNames = new HashSet<>();
95	    ServerServiceDefinition.Builder builder =
96	        ServerServiceDefinition.builder(orig.getServiceDescriptor().getName());
97	
98	    // Add `upload` method with zerocopy marshaller.
99	    MethodDescriptor<SendContainerRequest, SendContainerResponse> uploadMethod =
100	        getUploadMethod();
101	    addZeroCopyMethod(orig, builder, uploadMethod,
102	        sendContainerZeroCopyMessageMarshaller);
103	    methodNames.add(uploadMethod.getFullMethodName());
104	
105	    // Add `download` method with zerocopy marshaller.
106	    MethodDescriptor<CopyContainerRequestProto, CopyContainerResponseProto>
107	        downloadMethod = getDownloadMethod();
108	    addZeroCopyMethod(orig, builder, downloadMethod,
109	        copyContainerZeroCopyMessageMarshaller);
110	    methodNames.add(downloadMethod.getFullMethodName());
111	
112	    // Add other methods as is.
113	    orig.getMethods().stream().filter(
114	        x -> !methodNames.contains(x.getMethodDescriptor().getFullMethodName())
115	    ).forEach(
116	        builder::addMethod
117	    );
118	
119	    return builder.build();
120	  }
121	
122	  private static <Req extends MessageLite, Resp> void addZeroCopyMethod(
123	      ServerServiceDefinition orig,
124	      ServerServiceDefinition.Builder newServiceBuilder,
125	      MethodDescriptor<Req, Resp> origMethod,
126	      ZeroCopyMessageMarshaller<Req> zeroCopyMarshaller) {
127	    MethodDescriptor<Req, Resp> newMethod = origMethod.toBuilder()
128	        .setRequestMarshaller(zeroCopyMarshaller)
129	        .build();
130	    @SuppressWarnings("unchecked")
131	    ServerCallHandler<Req, Resp> serverCallHandler =
132	        (ServerCallHandler<Req, Resp>) orig.getMethod(
133	            newMethod.getFullMethodName()).getServerCallHandler();
134	    newServiceBuilder.addMethod(newMethod, serverCallHandler);
135	  }
136	
137	  @Override
138	  public void download(CopyContainerRequestProto request,
139	      StreamObserver<CopyContainerResponseProto> responseObserver) {
140	    long containerID = request.getContainerID();
141	    CopyContainerCompression compression = fromProto(request.getCompression());
142	    LOG.info("Streaming container data ({}) to other datanode " +
143	        "with compression {}", containerID, compression);
144	    OutputStream outputStream = null;
145	    try {
146	      outputStream = new CopyContainerResponseStream(
147	          // gRPC runtime always provides implementation of CallStreamObserver
148	          // that allows flow control.
149	          (CallStreamObserver<CopyContainerResponseProto>) responseObserver,
150	          containerID, BUFFER_SIZE);
151	      source.copyData(containerID, outputStream, compression);
152	    } catch (IOException e) {
153	      LOG.warn("Error streaming container {}", containerID, e);
154	      responseObserver.onError(e);
155	    } finally {
156	      // output may have already been closed, ignore such errors
157	      IOUtils.cleanupWithLogger(LOG, outputStream);
158	
159	      if (copyContainerZeroCopyMessageMarshaller != null) {
160	        InputStream popStream =
161	            copyContainerZeroCopyMessageMarshaller.popStream(request);
162	        if (popStream != null) {
163	          IOUtils.cleanupWithLogger(LOG, popStream);
164	        }
165	      }
166	    }
167	  }
168	
169	  @Override
170	  public StreamObserver<SendContainerRequest> upload(
171	      StreamObserver<SendContainerResponse> responseObserver) {
172	    return new SendContainerRequestHandler(importer, responseObserver,
173	        sendContainerZeroCopyMessageMarshaller);
174	  }
175	}
