86	    LOG.info("Initializing replication server with thread count = {}"
87	            + " queue length = {}",
88	        replicationConfig.getReplicationMaxStreams(),
89	        replicationConfig.getReplicationQueueLimit());
90	    ThreadFactory threadFactory = new ThreadFactoryBuilder()
91	        .setDaemon(true)
92	        .setNameFormat(threadNamePrefix + "ReplicationContainerReader-%d")
93	        .build();
94	    this.executor = new ThreadPoolExecutor(
95	        replicationServerWorkers,
96	        replicationServerWorkers,
97	        60,
98	        TimeUnit.SECONDS,
99	        new LinkedBlockingQueue<>(replicationQueueLimit),
100	        threadFactory);
101	
102	    init(replicationConfig.isZeroCopyEnable());
103	  }
