118	        SslContextBuilder sslContextBuilder = SslContextBuilder.forServer(caClient.getKeyManager());
119	
120	        sslContextBuilder = GrpcSslContexts.configure(
121	            sslContextBuilder, secConf.getGrpcSslProvider());
122	
123	        sslContextBuilder.clientAuth(ClientAuth.REQUIRE);
124	        sslContextBuilder.trustManager(caClient.getTrustManager());
125	
126	        nettyServerBuilder.sslContext(sslContextBuilder.build());
127	      } catch (IOException ex) {
128	        throw new IllegalArgumentException(
129	            "Unable to setup TLS for secure datanode replication GRPC "
130	                + "endpoint.", ex);
131	      }
132	    }
133	
134	    server = nettyServerBuilder.build();
135	  }
